-- V202608141001__DICT-REFACTOR-002-operator-remarks.sql
-- 把保留字典的 remark 改写成运营人员看得懂的描述（admin 字典数据页头部展示）。

UPDATE sys_dict_type SET remark = '系统日志的成功/失败标记，登录日志和操作日志里标每条操作是成功还是失败' WHERE dict_type = 'sys_common_status';
UPDATE sys_dict_type SET remark = '登录设备类型（小程序/苹果/安卓/电脑），在线用户和登录日志里显示从哪种设备登入' WHERE dict_type = 'sys_device_type';
UPDATE sys_dict_type SET remark = '客户端登录授权方式（密码/短信/邮件/三方/小程序），客户端管理里配允许哪些方式登录' WHERE dict_type = 'sys_grant_type';
UPDATE sys_dict_type SET remark = '通用启用/停用开关，后台角色、岗位、菜单、员工账号等大量地方用它控制启不启用' WHERE dict_type = 'sys_normal_disable';
UPDATE sys_dict_type SET remark = '系统通知公告的开关状态，发通知时标这条是正常展示还是已关闭' WHERE dict_type = 'sys_notice_status';
UPDATE sys_dict_type SET remark = '系统消息分类，发系统消息时区分是通知还是公告' WHERE dict_type = 'sys_notice_type';
UPDATE sys_dict_type SET remark = '后台操作日志的动作类型，标每条记录是新增、修改、删除、导出还是其他' WHERE dict_type = 'sys_oper_type';
UPDATE sys_dict_type SET remark = '菜单显示或隐藏，后台菜单管理里配一个菜单在侧边栏显不显示' WHERE dict_type = 'sys_show_hide';
UPDATE sys_dict_type SET remark = '性别选项，员工资料、猪只、仔猪耳标等录性别时选男/女/未知' WHERE dict_type = 'sys_user_sex';
UPDATE sys_dict_type SET remark = '系统参数的是/否开关，后台系统配置和文件存储配置里用' WHERE dict_type = 'sys_yes_no';
UPDATE sys_dict_type SET remark = '通用是/否开关，各种是否字段用它，如是否租赁、是否买断、是否已损坏' WHERE dict_type = 'djs_yes_no';
UPDATE sys_dict_type SET remark = '通用启用/停用状态，班组、库位、门店产品关联等需要启停的地方共用这一个' WHERE dict_type = 'djs_common_status';
UPDATE sys_dict_type SET remark = '农场的启用/停用状态，单农场暂用不到，将来多农场时区分农场是否在用' WHERE dict_type = 'djs_farm_status';
UPDATE sys_dict_type SET remark = '门店合作状态，门店管理里标一家店是合作中、已终止还是装修中' WHERE dict_type = 'djs_store_status';
UPDATE sys_dict_type SET remark = '门店类型，门店管理和小程序选门店时区分直营还是加盟' WHERE dict_type = 'djs_store_type';
UPDATE sys_dict_type SET remark = '供应商合作状态，供应商管理里标一家供应商是合作中还是已终止' WHERE dict_type = 'djs_supplier_status';
UPDATE sys_dict_type SET remark = '供应商类型（饲料/种猪/药品/种子/其他），供应商管理和采购选供应商时按类型筛' WHERE dict_type = 'djs_supplier_type';
UPDATE sys_dict_type SET remark = '供应商结算方式，供应商资料里记跟这家怎么结账：现款现货、月结还是季结' WHERE dict_type = 'djs_settle_type';
UPDATE sys_dict_type SET remark = '猪的品种（恩施黑猪/两头乌/杜洛克等），引种登记选品种，养殖端猪卡和猪肉追溯页显示品种' WHERE dict_type = 'djs_pig_breed';
UPDATE sys_dict_type SET remark = '猪的品系（恩施黑猪/两头乌等），引种登记选品系，和品种一起拼进耳号里区分血统' WHERE dict_type = 'djs_pig_strain';
UPDATE sys_dict_type SET remark = '猪的公母，引种和阉割时录入，猪卡、清单、猪肉追溯页显示' WHERE dict_type = 'djs_pig_sex';
UPDATE sys_dict_type SET remark = '猪的类型（种母猪/种公猪/仔猪/育肥猪），决定这头猪走不走繁殖流程，猪只列表按类型筛选' WHERE dict_type = 'djs_pig_type';
UPDATE sys_dict_type SET remark = '种母猪当前繁殖阶段（后备/配种/分娩/断奶/流产/空怀/返情/终止），猪卡和看板显示母猪现在处在哪一步' WHERE dict_type = 'djs_pig_lifecycle';
UPDATE sys_dict_type SET remark = '猪只经历的动作（引种/配种/分娩/断奶/查情/死亡/淘汰/阉割/转移/出栏等），状态记录里每笔标是哪种操作' WHERE dict_type = 'djs_pig_status_event';
UPDATE sys_dict_type SET remark = '猪只离场的最终原因（死亡/淘汰/出栏），列表和详情页显示这头猪最后怎么走的' WHERE dict_type = 'djs_pig_end_reason';
UPDATE sys_dict_type SET remark = '育种配置里区分是按品种还是按品系管理，育种页四个页签靠它分组' WHERE dict_type = 'djs_breed_strain_type';
UPDATE sys_dict_type SET remark = '栋舍类型（配种舍/妊娠舍/产房/保育舍/育肥舍/隔离舍等），建栋舍和转猪时选，可自行增删' WHERE dict_type = 'djs_barn_type';
UPDATE sys_dict_type SET remark = '栏位类型（大栏/限位栏/产床/散栏/保育栏），建栋舍时按类型批量生成栏位，决定每栏能装多少头' WHERE dict_type = 'djs_pen_type';
UPDATE sys_dict_type SET remark = '母猪配种后未孕的异常类型：返情、流产、空怀，养殖工录返空事件时选一种' WHERE dict_type = 'djs_abnormal';
UPDATE sys_dict_type SET remark = '母猪查情的结果：阳性、阴性、待复查，用于查情记录的历史回看' WHERE dict_type = 'djs_heat_result';
UPDATE sys_dict_type SET remark = '母猪配种方式：本场公猪配种还是外购精液配种，养殖工录配种时选' WHERE dict_type = 'djs_mating_method';
UPDATE sys_dict_type SET remark = '外购精液配种时选用的精液品种（杜洛克/长白/大白/皮特兰），配种录入时下拉选' WHERE dict_type = 'djs_semen';
UPDATE sys_dict_type SET remark = '母猪返空的具体原因（配种失败/早期流产/胚胎死亡/疾病/营养不良等），返空录入时备选' WHERE dict_type = 'djs_null_return';
UPDATE sys_dict_type SET remark = '引进种猪的来源：外部引种还是场内自繁转入，后台引种登记时选' WHERE dict_type = 'djs_introduce_type';
UPDATE sys_dict_type SET remark = '猪只死亡的病因分类（胀气/回肠炎/腹泻/呼吸道等），养殖工录死亡时选，可自行增删' WHERE dict_type = 'djs_death_reason';
UPDATE sys_dict_type SET remark = '死猪的处置去向：无害化、食用还是其他，养殖工录死亡事件时必选' WHERE dict_type = 'djs_death_dest';
UPDATE sys_dict_type SET remark = '淘汰猪只的原因：年龄、疾病、性能不佳或其他，养殖工录淘汰时选' WHERE dict_type = 'djs_culling_reason';
UPDATE sys_dict_type SET remark = '淘汰猪只的去向：外卖、无害化或其他，养殖工录淘汰时必选，可自行增删' WHERE dict_type = 'djs_culling_dest';
UPDATE sys_dict_type SET remark = '肥猪出栏的目的地：送宰、外销或其他，养殖工录出栏时选，默认送宰' WHERE dict_type = 'djs_market_dest';
UPDATE sys_dict_type SET remark = '免疫用药时打的疫苗种类（猪瘟/口蹄疫/蓝耳/伪狂犬等），用药记录选免疫时联动选，可自行增删' WHERE dict_type = 'djs_vaccine_type';
UPDATE sys_dict_type SET remark = '药品分类（抗生素/疫苗/营养剂/消毒剂等），养殖端药品库列表按类型筛选和展示药品用' WHERE dict_type = 'djs_med_type';
UPDATE sys_dict_type SET remark = '药品领用台账的动作：领用、退回、损耗，每笔药品出入库流水用它标是领走还是退回或损耗掉' WHERE dict_type = 'djs_med_pick_action';
UPDATE sys_dict_type SET remark = '给猪用药的原因（腹泻/发热/咳嗽/关节炎/产后保健等），录用药记录时选为什么用这个药' WHERE dict_type = 'djs_medicine_reason';
UPDATE sys_dict_type SET remark = '用药用途分保健、治疗、免疫，录用药记录时选；选免疫会再弹疫苗种类下拉' WHERE dict_type = 'djs_medicine_use_type';
UPDATE sys_dict_type SET remark = '给药方式（拌料/饮水/注射/口服/喷雾/涂抹），录用药记录时选怎么给的药' WHERE dict_type = 'djs_medicine_way';
UPDATE sys_dict_type SET remark = '用药剂量单位（毫升/升/毫克/克/千克/片），养殖工领药填用药量时选单位' WHERE dict_type = 'djs_medicine_unit';
UPDATE sys_dict_type SET remark = '用药记录是单只用药还是批量用药，批量给一群猪同时用药时用它区分主记录和明细' WHERE dict_type = 'djs_drug_type';
UPDATE sys_dict_type SET remark = '作物大类（水稻/小麦/玉米/蔬菜/水果等），地块选作物和农事页显示种的是什么' WHERE dict_type = 'djs_crop';
UPDATE sys_dict_type SET remark = '作物的科属分类（茄科/葫芦科/十字花科等），配置作物主数据时选，列表详情回显' WHERE dict_type = 'djs_crop_family';
UPDATE sys_dict_type SET remark = '地块类型（保育/露天/单体棚/连体棚），建地块和地块列表里区分种在哪种地上' WHERE dict_type = 'djs_plot_type';
UPDATE sys_dict_type SET remark = '地块当前状态（空闲/种植中/采摘中），随种植进度自动流转，地块列表和灾害页看' WHERE dict_type = 'djs_plot_status';
UPDATE sys_dict_type SET remark = '地块是自有还是租来的，建地块时勾选，详情里看' WHERE dict_type = 'djs_plot_lease';
UPDATE sys_dict_type SET remark = '种植计划的旬别（上旬/中旬/下旬），和月份拼成"6月中旬"显示计划时间' WHERE dict_type = 'djs_plant_period';
UPDATE sys_dict_type SET remark = '种植计划进度（待开始/进行中/已完成/已延期），计划列表显示，延期的自动标红' WHERE dict_type = 'djs_plant_plan_status';
UPDATE sys_dict_type SET remark = '作物或种植计划的季节（春/夏/秋/冬），配作物和筛计划时选' WHERE dict_type = 'djs_planting_season';
UPDATE sys_dict_type SET remark = '片区归哪个基地大区（如一期基地/二期基地），建地块片区时选，可自己增删' WHERE dict_type = 'djs_zone_belong';
UPDATE sys_dict_type SET remark = '地块土壤类型（壤土/砂土/黏土等），建地块时填，详情回显' WHERE dict_type = 'djs_soil_type';
UPDATE sys_dict_type SET remark = '地块土壤肥力等级（高/中/低/贫瘠），建地块时填，详情里看' WHERE dict_type = 'djs_soil_fertility';
UPDATE sys_dict_type SET remark = '地块光照情况（充足/一般/半阴/阴），建地块时填，详情回显' WHERE dict_type = 'djs_light_condition';
UPDATE sys_dict_type SET remark = '地块地势（平地/缓坡/陡坡/梯田），建地块时填，详情里看' WHERE dict_type = 'djs_terrain_condition';
UPDATE sys_dict_type SET remark = '地块排水情况（良好/一般/较差），建地块时填，详情回显' WHERE dict_type = 'djs_drain_condition';
UPDATE sys_dict_type SET remark = '农事活动类型（翻耕/整地/施肥/移栽/除草/病虫防治/采收等），农事录入选哪类活，记录列表和地块时间轴按它分' WHERE dict_type = 'djs_farm_work_type';
UPDATE sys_dict_type SET remark = '整地活儿的耕法（深耕/浅耕/旋耕/深松），录整地农事时选' WHERE dict_type = 'djs_tillage_type';
UPDATE sys_dict_type SET remark = '整地用什么方式（人工/机械/混合），录整地农事时选' WHERE dict_type = 'djs_tillage_way';
UPDATE sys_dict_type SET remark = '灾害种类（虫害/风灾/洪涝/干旱/病害），录灾害时选，灾害记录页按它筛' WHERE dict_type = 'djs_disaster_type';
UPDATE sys_dict_type SET remark = '采摘明细进度（待采/采摘中/已完成/已延期），计划详情和地块旬别表回显' WHERE dict_type = 'djs_pick_status';
UPDATE sys_dict_type SET remark = '采收的菜发去哪（销售/毛菜保鲜室/果蔬月台/损耗/饲喂），录采收时选，走去向决定进哪个下游台账' WHERE dict_type = 'djs_pick_dest';
UPDATE sys_dict_type SET remark = '仓库分类（鲜肉仓/蔬菜仓/物资仓/包材仓），新建仓库时选属于哪类仓' WHERE dict_type = 'djs_warehouse_type';
UPDATE sys_dict_type SET remark = '物资分类（包材/白条/蔬菜/鸡蛋/干货/果蔬/采食原料/药品/种子），物资领用和出入库流水按它筛选' WHERE dict_type = 'djs_mat_type';
UPDATE sys_dict_type SET remark = '自产产品归的大类（猪肉/果蔬/白条/干货/鸡蛋/礼盒/包材等），产品、库存、追溯、损耗、需求、发货全流程都按它区分' WHERE dict_type = 'djs_belong_type';
UPDATE sys_dict_type SET remark = '外购采购的品类（原料/饲料/药品/肥料/农药/种子/设备/包材），录外购商品时选是买的哪类' WHERE dict_type = 'djs_buy_class';
UPDATE sys_dict_type SET remark = '产品来源分自产还是外购，产品管理里拆产品/商品/礼盒三个入口靠它区分' WHERE dict_type = 'djs_product_type';
UPDATE sys_dict_type SET remark = '产品是成品还是原材料，仓库领用只领原材料、打包分割走成品都靠它判断' WHERE dict_type = 'djs_product_attr';
UPDATE sys_dict_type SET remark = '自产产品归哪个生产车间（燎毛间/分割间/肉品·蔬菜·门店·礼盒打包间），决定打包工序分流和追溯标记' WHERE dict_type = 'djs_product_workshop';
UPDATE sys_dict_type SET remark = '库位分区（干货库/白条/鲜品/冻品/物资/蔬菜/包材/种植库/养殖库等），入库领用打包按库位类型分流' WHERE dict_type = 'djs_location_type';
UPDATE sys_dict_type SET remark = '出入库流水的业务类型（采购入库/领用/退回/损耗/白条出库/分割入库/发货/盘点/打包/转移等），仓库流水台账每笔标动了什么' WHERE dict_type = 'djs_flow_type';
UPDATE sys_dict_type SET remark = '出入库流水的方向，标这笔是入库还是出库' WHERE dict_type = 'djs_inout_type';
UPDATE sys_dict_type SET remark = '出库去哪（厨房/矿山/大冶门店/个人/投喂/部门领用/发货月台/白条分割/生产领用等），领用发货转移出库时标去向' WHERE dict_type = 'djs_stock_out_dest';
UPDATE sys_dict_type SET remark = '盘点每行的结果（正常/异常/计损），仓库和门店盘点录入时按盘点差异判定，异常和计损会触发损耗' WHERE dict_type = 'djs_check_result';
UPDATE sys_dict_type SET remark = '盘点单的进度（草稿/进行中/已完成），仓库和门店盘点单都用它标当前到哪一步' WHERE dict_type = 'djs_check_status';
UPDATE sys_dict_type SET remark = '损耗类型（毛菜处理/运输/录入/生产/盘点/预冷/分割/燎毛损耗），每日损耗总览按类型汇总' WHERE dict_type = 'djs_loss_type';
UPDATE sys_dict_type SET remark = '饲料饲喂的来源（毛菜间还是仓库物资领用），记录这笔饲喂料从哪个环节来，用于算果蔬损耗' WHERE dict_type = 'djs_feed_type';
UPDATE sys_dict_type SET remark = '毛菜蔬菜处理后成品的去向（入库/上月台/做有机饲料），处理录入时选处理完往哪走' WHERE dict_type = 'djs_handle_target';
UPDATE sys_dict_type SET remark = '退货和损耗的原因（货品损坏/过期失效/规格错/客户退还/盘亏/其他），退货损耗表单里选为什么退或损' WHERE dict_type = 'djs_return_loss_reason';
UPDATE sys_dict_type SET remark = '猪只燎毛处理进度（待处理/已完成），仓库燎毛记录列表按此筛选查看' WHERE dict_type = 'djs_burn_status';
UPDATE sys_dict_type SET remark = '白条从燎毛到入库再到分割的全流程状态，后台和小程序看白条走到哪一步' WHERE dict_type = 'djs_bar_status';
UPDATE sys_dict_type SET remark = '白条入库是从燎毛间来还是从分割间来，入库时标来源' WHERE dict_type = 'djs_bar_in_method';
UPDATE sys_dict_type SET remark = '白条出库走哪条路：发货领用、进分割间、还是后台直接取走' WHERE dict_type = 'djs_bar_out_method';
UPDATE sys_dict_type SET remark = '猪肉分割产出的部位分类（精瘦肉/部位肉/骨类/猪皮/碎料），分割和成品入库按部位归类' WHERE dict_type = 'djs_pig_cut_part';
UPDATE sys_dict_type SET remark = '白条领用分割的进度（待领用/已领用/分割中/已完成），后台白条领用记录页按此筛选' WHERE dict_type = 'djs_pig_cut_status';
UPDATE sys_dict_type SET remark = '白条领用去哪里：分割车间、发货月台、还是仓库出库，只有去分割才算进分割统计' WHERE dict_type = 'djs_pig_cut_out_type';
UPDATE sys_dict_type SET remark = '毛菜处理进度（待处理/处理中/已完成），小程序燎毛间净菜处理提交时推进' WHERE dict_type = 'djs_veg_handle_status';
UPDATE sys_dict_type SET remark = '果蔬月台收货入库进度（待入库/入库中/已入库）' WHERE dict_type = 'djs_veg_receive_status';
UPDATE sys_dict_type SET remark = '果蔬月台收的是自产还是外购，决定按已发月台还是按供应商验收入库' WHERE dict_type = 'djs_veg_receive_type';
UPDATE sys_dict_type SET remark = '蔬菜处理明细是采收还是处理这道工序，第一条必须是采收' WHERE dict_type = 'djs_record_type';
UPDATE sys_dict_type SET remark = '产品打包进度（待打包/已打包/已出库待发货），打包环节按此推进和查询' WHERE dict_type = 'djs_pack_status';
UPDATE sys_dict_type SET remark = '打包时选成品送去哪里：发货月台、个人邮寄、还是做礼盒' WHERE dict_type = 'djs_pack_send_dest';
UPDATE sys_dict_type SET remark = '这批货怎么交付：发货、邮寄、还是销售，发货单和打包记录都用它标' WHERE dict_type = 'djs_deliver_type';
UPDATE sys_dict_type SET remark = '需求单的产品业态（白条/猪/果蔬/干货/鸡蛋/礼盒/其他），需求管理页按业态分标签录单，发货和看板也按它取数' WHERE dict_type = 'djs_demand_product_type';
UPDATE sys_dict_type SET remark = '需求单进度（草稿/已提交/已确认/部分发货/已完成/已取消），需求列表筛选和发货时判断这单还能不能发就看它' WHERE dict_type = 'djs_demand_status';
UPDATE sys_dict_type SET remark = '门店需求的收货方式：门店自取配送还是个人邮寄，门店下单时选，配送和邮寄走不同流程' WHERE dict_type = 'djs_demand_mailing_type';
UPDATE sys_dict_type SET remark = '门店视角看自己需求单的进度（待确认/已确认/已发货/确认到店/已删除），门店端需求列表显示到哪一步了' WHERE dict_type = 'djs_store_demand_status';
UPDATE sys_dict_type SET remark = '派工任务的进度阶段（计划中/已派工/执行中/已完成/已回执），小程序派工卡上显示这个活干到哪了' WHERE dict_type = 'djs_dispatch_stage';
UPDATE sys_dict_type SET remark = '发货单进度（待发货/清点中/已发车/已到货），发货月台清点发车、门店确认收货时状态往前推' WHERE dict_type = 'djs_shipment_status';
UPDATE sys_dict_type SET remark = '退货是往哪个方向退：顾客退门店、门店退仓库、仓库退供应商，目前主要走门店退回仓库这条' WHERE dict_type = 'djs_return_direction';
UPDATE sys_dict_type SET remark = '仓库退货单进度（待确认/已确认/已驳回），仓管确认或驳回门店退回的货时用' WHERE dict_type = 'djs_return_status';
UPDATE sys_dict_type SET remark = '门店退回货物两步进度：待仓库确认、已入库；门店在小程序提交退回、仓管确认收货入库' WHERE dict_type = 'djs_store_return_status';
UPDATE sys_dict_type SET remark = '门店销售明细是怎么来的：人工手录还是Excel导入，门店经营录销售数据时标来源' WHERE dict_type = 'djs_sale_source';
UPDATE sys_dict_type SET remark = '门店会员等级（普通/重要价值客户/重要保持客户），门店开单选会员时区分等级' WHERE dict_type = 'djs_member_level';
UPDATE sys_dict_type SET remark = '门店现场分割生码时选的猪肉部位（前腿肉/五花肉/排骨/肘子/大排），现场分白条打追溯码用' WHERE dict_type = 'djs_pork_cut_product';
UPDATE sys_dict_type SET remark = '门店退回、盘点、打包时能选的猪肉产品清单，客户可在后台自己增删产品' WHERE dict_type = 'djs_pork_return_product';
UPDATE sys_dict_type SET remark = '门店退回选白条产品时的候选清单，按重量退货，客户可在后台配置具体白条产品' WHERE dict_type = 'djs_white_bar_return_product';
UPDATE sys_dict_type SET remark = '追溯码分哪种货：猪肉/果蔬/礼盒，生码和顾客扫码看结果时按这个走对应展示' WHERE dict_type = 'djs_trace_code_type';
UPDATE sys_dict_type SET remark = '追溯时间线上的每个节点（出栏/屠宰/排酸/入库/发货/到店，白条和果蔬各自节点），顾客扫码看货从哪来到哪去' WHERE dict_type = 'djs_trace_content';
